from enum import Enum
from taf.analyzer.base import LogEntry


class Direction(Enum):
    sent = 1
    received = 2


class NetconfLogEntry(LogEntry):
    """
    Log entry representing the reception or sending of a NETCONF message.
    """
    def __init__(
            self,
            message,
            **kwargs):
        """
        Create a NETCONF log entry.

        :param NetconfMessage message: NETCONF message
        """
        super(NetconfLogEntry, self).__init__(**kwargs)
        self._message = message

    @property
    def message(self):
        """
        NETCONF message.
        """
        return self._message

    def __str__(self):
        """
        Return timestamp, class name and message string.
        """
        return "{timestamp} {message_type} {message}".format(
            timestamp=self.timestamp,
            message_type=self._message.type,
            message=self._message)
